#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

#define THREAD_EXIT_VALUE 42

// Function executed by the worker thread
void* worker_function(void* arg) {
    printf("Worker thread started.\n");

    // Dynamically allocate memory for the return value
    int *status_ptr = malloc(sizeof(int));
    if (status_ptr == NULL) {
        perror("malloc failed");
        // Exit with NULL status on allocation error
        pthread_exit(NULL);
    }

    *status_ptr = THREAD_EXIT_VALUE;
    printf("Worker thread exiting, returning status: %d.\n", *status_ptr);

    // Terminate the calling thread and return the status pointer
    pthread_exit((void*)status_ptr);
    // Execution never reaches here
}

int main() {
    pthread_t worker_tid;
    void *thread_return_value = NULL;
    int s;

    // Create the joinable worker thread
    s = pthread_create(&worker_tid, NULL, worker_function, NULL);
    if (s != 0) {
        errno = s;
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    // Wait for the worker thread and retrieve its exit status
    s = pthread_join(worker_tid, &thread_return_value);
    if (s != 0) {
        errno = s;
        perror("pthread_join");
        return EXIT_FAILURE;
    }

    // Process the returned status
    if (thread_return_value != NULL) {
        int *status = (int*)thread_return_value;
        printf("Main thread retrieved exit code: %d\n", *status);

        // Crucial: Free the memory allocated by the exited thread
        free(status);
    } else {
        printf("Main thread retrieved NULL exit code (possible thread error).\n");
    }

    return EXIT_SUCCESS;
}
